var HORO={
 '白羊座':['今天适合主动出击，别等机会来找你。','小冲动可能带来大惊喜，但记得留后路。'],
 '金牛座':['稳扎稳打的一天，财务上有好消息。','享受美食与安静，会让你恢复能量。'],
 '双子座':['沟通运强，适合把想法说出来。','信息繁杂，学会筛选才是关键。'],
 '巨蟹座':['家人或老友会给你温暖。','情绪起伏正常，别憋在心里。'],
 '狮子座':['你的主场感很强，适合带队。','适度示弱反而更有人缘。'],
 '处女座':['细节决定成败，今天尤其如此。','整理环境会让你思路更清。'],
 '天秤座':['人际关系迎来平衡点。','纠结时，问自己最想要什么。'],
 '天蝎座':['直觉很准，值得相信。','深层话题会带来共鸣。'],
 '射手座':['想出发就去，别等完美时机。','乐观会传染，今天你就是光源。'],
 '摩羯座':['长期主义的回报开始显现。','把大目标拆小，今天就能动。'],
 '水瓶座':['独特想法会被看见。','保持独立，也别忘了协作。'],
 '双鱼座':['灵感充沛，适合创作。','温柔待人，也善待自己。']
};
function signOf(dateStr){
  var d=new Date(dateStr); if(isNaN(d.getTime())) return null;
  var m=d.getMonth()+1, day=d.getDate();
  var cut=[[1,20,'摩羯座'],[2,19,'水瓶座'],[3,20,'双鱼座'],[4,20,'白羊座'],[5,21,'金牛座'],[6,21,'双子座'],[7,22,'巨蟹座'],[8,23,'狮子座'],[9,23,'处女座'],[10,23,'天秤座'],[11,22,'天蝎座'],[12,22,'射手座'],[13,0,'摩羯座']];
  for(var i=0;i<cut.length;i++){ if(m<cut[i][0] || (m===cut[i][0] && day<=cut[i][1])) return cut[i][2]; }
  return '摩羯座';
}
function horoscope(sign){ var bank=HORO[sign]||['今天平平淡淡。']; return bank[Math.floor(Math.random()*bank.length)]; }
var EXPORTS={signOf:signOf,horoscope:horoscope,HORO:HORO};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HoroscopeForgePure = EXPORTS; }
